#include "mpe_state.hpp"
#include <algorithm>
#include <cmath>
namespace latticewake { bool MpeState::member(int c) const { if(c<1||c>16)return false; if(config_.mode==MpeMode::legacy)return c==config_.masterChannel; if(config_.mode==MpeMode::lower)return c>config_.masterChannel&&c<=config_.masterChannel+config_.memberCount; return c<config_.masterChannel&&c>=config_.masterChannel-config_.memberCount; }
bool MpeState::noteOn(int c,int n){if(!member(c)||n<0||n>127||active(c))return false;notes_.push_back({c,n,{}});return true;} bool MpeState::noteOff(int c,int n){auto it=std::find_if(notes_.begin(),notes_.end(),[&](auto& s){return s.channel==c&&s.note==n;});if(it==notes_.end())return false;notes_.erase(it);return true;} bool MpeState::expression(int c,MpeExpression v){if(!member(c)||!std::isfinite(v.glide)||!std::isfinite(v.press)||!std::isfinite(v.slide)||v.glide < -1||v.glide>1||v.press<0||v.press>1||v.slide<0||v.slide>1)return false;auto it=std::find_if(notes_.begin(),notes_.end(),[&](auto& s){return s.channel==c;});if(it==notes_.end())return false;it->expression=v;return true;} std::optional<MpeNoteState> MpeState::active(int c)const{auto it=std::find_if(notes_.begin(),notes_.end(),[&](const auto& s){return s.channel==c;});if(it==notes_.end())return std::nullopt;return *it;} }
